/** A live cell's position on an unbounded grid, as `[x, y]`. */
export type Cell = [x: number, y: number];

const isSameCell = ([ax, ay]: Cell, [bx, by]: Cell): boolean =>
  ax === bx && ay === by;

/** Two cells are neighbours when they touch on any side or corner. */
const isNeighbour = (candidate: Cell, cell: Cell): boolean =>
  Math.abs(candidate[0] - cell[0]) <= 1 &&
  Math.abs(candidate[1] - cell[1]) <= 1 &&
  !isSameCell(candidate, cell);

const countLiveNeighbours = (cell: Cell, liveCells: Cell[]): number =>
  liveCells.filter((candidate) => isNeighbour(candidate, cell)).length;

/** Rule 1 & 2 & 3: a live cell survives with exactly 2 or 3 live neighbours. */
const survives = (liveNeighbours: number): boolean =>
  liveNeighbours === 2 || liveNeighbours === 3;

export function nextGeneration(liveCells: Cell[]): Cell[] {
  return liveCells.filter((cell) =>
    survives(countLiveNeighbours(cell, liveCells)),
  );
}
